MultiLanguageSpellData['ru'][85007] = {name = "Меховая подкладка - выносливость", additional_info = "Применение: 5 сек\nТребуется: Наручи\nИнгредиенты:\nЭтерниевая нить\n[q]Эта выкройка автоматически улучшается, когда ваш навык кожевничества повышается до 575.\n\n Укрепление наручей, увеличивающее выносливость на 195 .\n\n После укрепления наручи становятся персональным предметом. Чтобы меховая подкладка не теряла свои свойства, требуется навык кожевничества 400 или выше."}
MultiLanguageSpellData['ru'][85008] = {name = "Меховая подкладка - ловкость", additional_info = "Применение: 5 сек\nТребуется: Наручи\nИнгредиенты:\nЭтерниевая нить\n[q]Эта выкройка автоматически улучшается, когда ваш навык кожевничества повышается до 575.\n\n Укрепление наручей, увеличивающее ловкость на 130 .\n\n После укрепления наручи становятся персональным предметом. Чтобы меховая подкладка не теряла свои свойства, требуется навык кожевничества 400 или выше."}
