MultiLanguageSpellData['ru'][89893] = {name = "[q0]Монета Эльдре'Таласа", additional_info = "Применение: 2 сек 5\n[q]Некогда этот город был столицей высокорожденных, но после Великого Раскола обитель тайных магов королевы Азшары пришла в упадок и разорение. Теперь руины Эльдре'Таласа называются Забытым Городом.\n[q0]Монета Эльдре'Таласа\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][89894] = {name = "[q0]Обломок глефы", additional_info = "Применение: 2 сек 5\n[q]Это осколок крупного снаряда с тремя лезвиями, которыми стреляют эльфийские осадные орудия. Метатели глеф – не редкость и в наши дни, но этот древний осколок украшен резьбой, слишком вычурной и тонкой даже по меркам ночных эльфов.\n[q0]Обломок глефы\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][89895] = {name = "[q0]Спиральная раковина аммонита", additional_info = "Применение: 2 сек 5\n[q]Аммониты – вымерший подкласс головоногих моллюсков. Их раковины могут быть различной формы: от вытянутых, как шпиль, до закрученных, как бараний рог. Эта раковина сравнительно небольшая, но некоторые аммониты могли вырастать до гигантских размеров.\n[q0]Спиральная раковина аммонита\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][89896] = {name = "[q0]Кольцо с зеленым драконом", additional_info = "Применение: 2 сек 5\n[q]Скорее всего, на кольце изображен Эраникус, консорт Изеры. Он пал жертвой Изумрудного Кошмара, но позже заслужил прощение. По краю кольца выгравировано: \"Анду-фалах-дор!\"\n[q0]Кольцо с зеленым драконом\nСтановится персональным при поднятии"}
