MultiLanguageSpellData['ru'][90419] = {name = "[q0]Окаменевший щит Железной Звезды", additional_info = "Применение: 2 сек 5\n[q]Легенда говорит, что тан Железная Звезда из клана Черного Железа вырезал этот щит из священного древа высших эльфов, а затем с помощью чар придал щиту твердость камня.\n[q0]Окаменевший щит Железной Звезды\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][90420] = {name = "[q0]Горшок для цветов в форме черепа", additional_info = "Применение: 2 сек 5\n[q]Лесных троллей всегда привлекала растительная жизнь. На теле тролля вполне могут расти простейшие растения, например, мох или водоросли, отчего кожа троллей приобретает характерный зеленоватый оттенок.\n[q0]Горшок для цветов в форме черепа\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][90421] = {name = "[q0]Браслет из нефрита и монет", additional_info = "Применение: 2 сек 5\n[q]Браслет выполнен из нанизанных на серебряную цепочку тролльских монет и нефритовых бусин. Поскольку тролли питают тягу к золотым украшениям, вполне возможно, что серебряная цепочка – военный трофей. Монеты имеют необычную форму, на них изображены искаженные злобой лица женщин-троллей.\n[q0]Браслет из нефрита и монет\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][90422] = {name = "Рассечение титана", additional_info = nil}
MultiLanguageSpellData['ru'][90423] = {name = "[q0]Статуэтка Газ'риллы", additional_info = "Применение: 2 сек 5\n[q]Призвав эту огромную белую гидру из священных вод Зул'Фаррака, песчаные тролли начали поклоняться ей. Чешуя Газ'риллы наэлектризована, и даже эта статуэтка, кажется, переполнена энергией. Изображение гидры часто используется в графических орнаментах и архитектурных композициях, украшающих Зул'Фаррак.\n[q0]Статуэтка Газ'риллы\nСтановится персональным при поднятии"}
