MultiLanguageSpellData['ru'][90518] = {name = "[q0]Мифриловая цепь Кузни Гнева", additional_info = "Применение: 2 сек 5\n[q]Клан Кузни Гнева – один из древнейших кланов в истории дворфов Черного Железа. Эту цепь носил тан Кузня Гнева, предок генерала Кузни Гнева, главнокомандующего армии Черного Железа в Глубинах Черной горы.\n[q0]Мифриловая цепь Кузни Гнева\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][90519] = {name = "[q0]Тенегорнский посох с черепом", additional_info = "Применение: 2 сек 5\n[q]Клан Тенегорна оставил темный след в истории дворфов Черного Железа. Железный тан Тенегорн был исключительно жестоким деспотом, замучившим и убившим многих своих подданных. Традиционно его считают чернокнижником, однако согласно некоторым слухам он был одним из первых дворфийских шаманов.\n[q0]Тенегорнский посох с черепом\nСтановится персональным при поднятии"}
