MultiLanguageSpellData['ru'][106731] = {name = "Перевоплощение", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Вам становится доступен улучшенный вариант основного облика, используемого вашей специализацией. Вы можете принимать этот облик или сбрасывать его в течение 30 сек.\n\nБаланс: Избранный Элуны\n Усовершенствованный облик лунного совуха, в котором урон от заклинаний тайной магии и сил природы увеличивается на 25% во время затмения.\n\nСила зверя: Король джунглей\n Усовершенствованный облик кошки, в котором можно применять все способности, обычно требующие состояния незаметности. Способность \"Крадущийся зверь\" становится доступна в бою, способность \"Накинуться\" не требует находиться у цели за спиной.\n\nСтраж: Дитя Урсока\n Усовершенствованный облик медведя, в котором время восстановления атакующих способностей ближнего боя и способности \"Рык\" уменьшено до 1,5 сек.\n\nВосстановление: Древо Жизни\n Усовершенствованный облик Древа Жизни, в котором эффективность исцеляющих заклинаний увеличена на 15%, а броня усилена на 120%. Также усилены заклинания \"Жизнецвет\", \"Буйный рост\", \"Восстановление\" и \"Гнев деревьев\"."}
MultiLanguageSpellData['ru'][106732] = {name = "Баланс отменяет пассивный", additional_info = nil}
MultiLanguageSpellData['ru'][106733] = {name = "Облик кошки отменяет пассивный", additional_info = "[q]Modifies Cooldown 0:\nСмерч"}
