MultiLanguageSpellData['ru'][108211] = {name = "Похищающий жизнь яд", additional_info = "Применение: 3 сек\nТребуется: Одноручное оружие ближнего боя\n[q]Несмертельный яд, который наносится на оружие и действует в течение 1 ч. Каждый удар с вероятностью 50% отравляет противника на 10 сек. Последующие удары оружием по отравленной цели будут восстанавливать вам здоровье в объеме, равном 10% от нанесенного урона. [ Отравляющий укол : Отравляющий укол: \nМгновенно восстанавливает вам 5% от максимального запаса здоровья ](Вероятность срабатывания: 50%)"}
