MultiLanguageSpellData['ru'][109200] = {name = "Гаснущий свет", additional_info = "Мгновенное действие\n[q]Высасывает из цели Свет, затягивая ее в Сумрак. После окончания действия эффекта немедленно убивает цели, находящиеся в сумеречном мире. Цели, находящиеся в обычном мире, при этом затягиваются в мир сумеречный, а уровни угрозы обнуляются. Кроме того, в течение следующих 5 сек. угроза не создается."}
MultiLanguageSpellData['ru'][109206] = {name = "Крадущийся тигр, затаившаяся химера", additional_info = "[q]После получения урона в ближнем бою время восстановления способности \"Отрыв\" моментально уменьшается на 4 сек.\n\n После получения урона в дальнем бою или от заклинания время восстановления способности \"Сдерживание\" моментально уменьшается на 8 сек.\n\n Время восстановления этих эффектов составляет 2 сек.\n(Восстановление: 2с)"}
