MultiLanguageSpellData['ru'][110693] = {name = "Кольцо льда", additional_info = "{Мгновенное действие} {Восстановление: 25 сек}\n[q]Противники, находящиеся недалеко от заклинателя, примерзают к месту на срок до 8 сек. Нанесенный урон может прервать действие эффекта."}
