MultiLanguageSpellData['ru'][115002] = {name = "Призыв хваткой ненависти", additional_info = "Применение: 1 сек\n[q]Рядом с заклинателем возникает могущественное воплощение ненависти. Оно подтягивает врагов к себе и отравляет землю под их ногами."}
MultiLanguageSpellData['ru'][115003] = {name = "Карбонизация", additional_info = "Применение: 3 сек\n[q]Наносит 10000 ед. урона от магии льда раз в 1 сек. Во время действия заклинания противники задыхаются и ничего не могут сделать."}
