MultiLanguageSpellData['ru'][124465] = {name = "Прикосновение вампира", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Наносит 5 ед. урона от темной магии в течение 15 сек. Заклинатель восстанавливает 2% от максимального запаса маны каждый раз, когда противник получает урон от \"Прикосновения вампира\"."}
