MultiLanguageSpellData['ru'][139776] = {name = "Знамя империи богомолов", additional_info = "Применение: 2 сек\n[q]Хотя богомолы используют ветрошерсть и императорский шелк, предпочтение они отдают нетканым материалам, созданным из крыльев насекомых, включая их собственные. Это знамя создано из такого материала."}
