MultiLanguageSpellData['ru'][145045] = {name = "Мощный удар щитом", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Ударяет в противника щитом, нанося 69375 в 80625 ед. урона.\n\n Накапливает 3 ед. ярости."}
